function drawScreen8(x, w, h, o) { const m = o.mode || 'fms';
  if (m === 'fms') { x.fillStyle = '#0c1424'; x.fillRect(0, 0, w, h); ltxt(x, 'GLOBAL FUND MANAGER SURVEY', w / 2, h * 0.1, h * 0.06, '#9ab0d0', 'center'); ltxt(x, 'CASH HOLDINGS', w / 2, h * 0.25, h * 0.07, '#f4efe6', 'center'); const v = o.v == null ? 3.9 : o.v; ltxt(x, v.toFixed(1) + '%', w / 2, h * 0.47, h * 0.22, v < 4 ? '#ff5a4a' : '#3fd08a', 'center');
    const bx = w * 0.15, bw = w * 0.7, by = h * 0.7; x.fillStyle = '#24303a'; x.fillRect(bx, by, bw, h * 0.06); const p = k => bx + bw * (k - 2) / 5; x.fillStyle = '#ff5a4a'; x.fillRect(bx, by, p(4) - bx, h * 0.06); x.fillStyle = '#3fd08a'; x.fillRect(p(5), by, bx + bw - p(5), h * 0.06); x.fillStyle = '#fff'; x.fillRect(p(v) - 3, by - h * 0.03, 6, h * 0.12);
    ltxt(x, 'UNDER 4% = SELL SIGNAL', p(3), by + h * 0.13, h * 0.04, '#ff8a7a', 'center'); ltxt(x, 'OVER 5% = BUY', p(5.8), by + h * 0.13, h * 0.04, '#7ae0a0', 'center'); if (o.ai) { x.fillStyle = 'rgba(194,55,45,0.92)'; x.fillRect(w * 0.6, h * 0.06, w * 0.36, h * 0.14); ltxt(x, 'TOP RISK: AI BUBBLE (45%)', w * 0.78, h * 0.13, h * 0.04, '#fff', 'center'); } return; }
  if (m === 'boss') { const g = x.createLinearGradient(0, 0, 0, h); g.addColorStop(0, '#3a3046'); g.addColorStop(1, '#1a1826'); x.fillStyle = g; x.fillRect(0, 0, w, h); x.fillStyle = '#5a4a3a'; x.fillRect(0, h * 0.72, w, h * 0.28); x.fillStyle = '#c9a24a'; for (let i = 0; i < 5; i++) x.fillRect(w * (0.05 + i * 0.05), h * 0.25, w * 0.03, h * 0.45);
    const P = RH.stand('front'); P.face.blink = RH.blinkAt(o.t || 0); P.face.expr = o.expr || 'sly'; if (o.talk) { P.face.mouth = MOUTH[Math.floor((o.t || 0) * 9) % MOUTH.length]; P.arms[1] = { h: [0.6, 0.7 + 0.1 * Math.sin((o.t || 0) * 3)], hand: 'point' }; } P.bob = -0.02 * Math.sin((o.t || 0) * 2); RH.draw(x, CH.boss, P, w / 2, h * 1.55, h * 0.0062, { noShadow: true });
    x.fillStyle = '#c2372d'; x.beginPath(); x.arc(w * 0.05, h * 0.07, h * 0.022, 0, TAU); x.fill(); ltxt(x, 'LIVE · BOSS', w * 0.08, h * 0.07, h * 0.04, '#f4efe6'); return; }
  if (m === 'keynes') { x.fillStyle = '#1a140e'; x.fillRect(0, 0, w, h); paperBg(x, w, h, '#efe2c0'); x.strokeStyle = '#8a6a46'; x.lineWidth = 14; x.strokeRect(10, 10, w - 20, h - 20); const k = o.k == null ? 1 : o.k; const Q = ['"Worldly wisdom teaches that it is better', 'for reputation to fail conventionally', 'than to succeed unconventionally."']; Q.forEach((q, i) => { x.save(); x.globalAlpha = clamp(k * 3 - i, 0, 1); ltxt(x, q, w / 2, h * (0.3 + i * 0.15), h * 0.065, INK, 'center'); x.restore(); }); ltxt(x, 'J. M. Keynes, The General Theory, 1936', w / 2, h * 0.82, h * 0.05, '#7a5a3a', 'center'); return; }
  if (m === 'reel') { const k = o.k || 0; x.fillStyle = '#d8cfb8'; x.fillRect(0, 0, w, h); x.fillStyle = '#8a7a5a'; x.fillRect(0, h * 0.8, w, h * 0.2); ltxt(x, 'A PARABLE · WILDFIRE CAPITAL IS MADE UP', w / 2, h * 0.06, h * 0.045, '#3a2a1a', 'center');
    // rocket-shaped fund building + chart that rises then crashes
    const crash = o.crash || 0; const pk = 0.2 + 0.6 * Math.min(k, 1) * (1 - crash * 0.85); const gx = w * 0.56, gw = w * 0.38; x.strokeStyle = '#3a2a1a'; x.lineWidth = 3; x.strokeRect(gx, h * 0.18, gw, h * 0.56); x.strokeStyle = crash > 0.05 ? '#b02a22' : '#2f7a4a'; x.lineWidth = 8; x.beginPath(); for (let i = 0; i <= 40; i++) { const u = i / 40; let v = u < 0.7 ? Math.pow(u / 0.7, 1.6) * Math.min(1, k * 1.1) : Math.min(1, k * 1.1) * (1 - crash * Math.min(1, (u - 0.7) / 0.3) * 0.9); if (u > k + 0.02 && !crash) break; const px = gx + gw * u, py = h * 0.72 - h * 0.5 * v; i ? x.lineTo(px, py) : x.moveTo(px, py); } x.stroke();
    ltxt(x, crash > 0.05 ? 'MARGIN CALL' : 'AI CHIPS ONLY · 4:1 LEVERAGE', gx + gw / 2, h * 0.14, h * 0.045, crash > 0.05 ? '#b02a22' : '#3a2a1a', 'center');
    const rx = w * 0.25, ry = h * 0.78; x.fillStyle = '#c2372d'; x.beginPath(); x.moveTo(rx, ry - h * (0.55 + 0.05 * pk)); x.lineTo(rx + w * 0.07, ry - h * 0.35); x.lineTo(rx + w * 0.07, ry); x.lineTo(rx - w * 0.07, ry); x.lineTo(rx - w * 0.07, ry - h * 0.35); x.closePath(); x.fill(); x.fillStyle = '#f4efe6'; x.beginPath(); x.arc(rx, ry - h * 0.33, w * 0.03, 0, TAU); x.fill(); ltxt(x, 'WILDFIRE', rx, ry - h * 0.15, h * 0.04, '#fff', 'center'); ltxt(x, 'CAPITAL', rx, ry - h * 0.09, h * 0.04, '#fff', 'center');
    if (!crash) { x.fillStyle = 'rgba(255,170,40,' + (0.5 + 0.3 * Math.sin((o.t || 0) * 20)) + ')'; x.beginPath(); x.moveTo(rx - w * 0.05, ry); x.lineTo(rx, ry + h * 0.08 * (0.6 + 0.4 * Math.sin((o.t || 0) * 30))); x.lineTo(rx + w * 0.05, ry); x.fill(); }
    const P = crash > 0.3 ? RH.stand('q') : RH.anim.talk(o.t || 0, 'q'); P.face.expr = crash > 0.3 ? 'scared' : 'happy'; P.dir = 1; RH.draw(x, CH.jules2 || CH.jules, P, w * 0.43, h * 0.8, h * 0.0019, { noShadow: true });
    if (crash > 0.4) { x.fillStyle = '#24303a'; x.fillRect(w * 0.6, h * 0.48, w * 0.3, h * 0.12); ltxt(x, 'SOLD TO RIVAL AT A DISCOUNT', w * 0.75, h * 0.54, h * 0.032, '#f4efe6', 'center'); }
    x.fillStyle = 'rgba(0,0,0,0.08)'; for (let i = 0; i < 30; i++) x.fillRect(((i * 97 + Math.floor((o.t || 0) * 24) * 13) % w), 0, 1.5, h); x.strokeStyle = 'rgba(0,0,0,0.6)'; x.lineWidth = 18; x.strokeRect(0, 0, w, h); return; } }
CH.jules2 = RH.character({ name: 'Founder', skin: '#d8a070', head: { shape: 'round', w: 1, h: 1 }, ears: 'round', eyes: 'pie', nose: 'button', hair: { style: 'tuft', color: '#1e1612' }, hat: { type: 'none' }, body: { shape: 'slim' }, top: { type: 'tee', color: '#5a5a62', accent: '#f2c83a', emblem: 'none' }, legs: { color: '#24303a' } });
